:root {
  /* Surface & Background Canvas */
  --bg: #0f1112;
  --surface: #16181a;
  --surface-elevated: #1e2124;
  --line: #2e3236;
  --line-strong: #373b40;
  --line-soft: rgba(63, 63, 70, 0.50);

  /* Typography Hierarchy */
  --text-heading: #ffffff;
  --text: #e5e7eb;
  --text-body: #cfd3d8;
  --muted: #9ca3af;
  --faint: #6b7280;

  /* Brand Identity & Ramps */
  --brand: #ff6b35;
  --brand-deep: #7e1500;
  --brand-soft: rgba(255, 107, 53, 0.12);
  --brand-glow: rgba(255, 107, 53, 0.25);

  /* Immutable Semantic Statuses */
  --amber: #f0b23e;
  --amber-soft: rgba(240, 178, 62, 0.12);
  --amber-glow: rgba(240, 178, 62, 0.25);
  --teal: #4fb3a9;
  --teal-soft: rgba(79, 179, 169, 0.12);
  --teal-glow: rgba(79, 179, 169, 0.25);

  /* Section Domain Hues */
  --c-vocab: #447F9F;
  --c-phrasal: #3B8484;
  --c-colloc: #DE6E55;
  --c-grammar: #B06D29;
  --c-idioms: #62193D;
  --c-focus: #DCE62C;
  --c-practice: #B98CF0;
  --c-selfstudy: #6FC3DF;
  --c-todos-tutor: #9CA3AF;
  --c-todos-student: #FF6B35;

  /* Active Accent Pointer */
  --accent: var(--brand);
  --accent-deep: var(--brand-deep);
  --accent-soft: var(--brand-soft);
  --accent-glow: var(--brand-glow);

  /* Typography Families */
  --font-display: 'Fraunces', Georgia, serif;
  --font-head: 'Raleway', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;

  /* Gradients */
  --grad-canvas: radial-gradient(ellipse 80% 40% at 50% -10%, rgba(255, 107, 53, 0.08), transparent);
  --grad-brand-ramp: linear-gradient(135deg, var(--brand) 0%, var(--brand-deep) 100%);
  --grad-card-rail: linear-gradient(to bottom, var(--accent), color-mix(in srgb, var(--accent) 42%, #000));

  /* Radii */
  --radius-sm: 3px;
  --radius-md: 6px;
}
